Функция ПолучитьСальдоПоСчету(Счет)
	Если Счет = Неопределено Или Счет = Справочники.ПланСчетов.Основной.ПустаяСсылка() Тогда
		Возврат 0;
	КонецЕсли;

	// Дебет
	Запрос = Новый Запрос;
	Запрос.Текст = 
	"ВЫБРАТЬ
		СУММА(Х.Сумма) КАК Сумма
	ИЗ
		РегистрБухгалтерии.Хозрасчетный КАК Х
	ГДЕ
		Х.СчетДт В ИЕРАРХИИ &Счет";
	Запрос.УстановитьПараметр("Счет", Счет);
	Результат = Запрос.Выполнить();
	Выборка = Результат.Выбрать();
	СумДт = 0;
	Если Выборка.Следующий() Тогда
		Если ЗначениеЗаполнено(Выборка.Сумма) Тогда
			СумДт = Выборка.Сумма;
		КонецЕсли;
	КонецЕсли;

	// Кредит
	Запрос = Новый Запрос;
	Запрос.Текст = 
	"ВЫБРАТЬ
		СУММА(Х.Сумма) КАК Сумма
	ИЗ
		РегистрБухгалтерии.Хозрасчетный КАК Х
	ГДЕ
		Х.СчетКт В ИЕРАРХИИ &Счет";
	Запрос.УстановитьПараметр("Счет", Счет);
	Результат = Запрос.Выполнить();
	Выборка = Результат.Выбрать();
	СумКт = 0;
	Если Выборка.Следующий() Тогда
		Если ЗначениеЗаполнено(Выборка.Сумма) Тогда
			СумКт = Выборка.Сумма;
		КонецЕсли;
	КонецЕсли;

	СальдоДтМинКт = СумДт - СумКт;

	Если Счет.Вид = Перечисление.ВидСчета.Пассивный Тогда
		Возврат(СумКт - СумДт);
	Иначе
		Возврат(СальдоДтМинКт);
	КонецЕсли;
КонецФункции
